  var createUniqueMaterials = (base, extras) => {
    const existing = new Set(base.map((m2) => m2.id));
    const makeUniqueId = (origId, name) => {
      const packaging = name.match(/\(([^)]+)\)/)?.[1]?.replace(/\s+/g, "").toLowerCase() || "v2";
      let newId = `${origId}-${packaging}`;
      let i4 = 2;
      while (existing.has(newId)) {
        newId = `${origId}-${packaging}-${i4++}`;
      }
      return newId;
    };
    const adjustedExtras = extras.map((m2) => {
      let id2 = m2.id;
      if (existing.has(id2)) {
        id2 = makeUniqueId(id2, m2.name);
      }
      existing.add(id2);
      return { ...m2, id: id2 };
    });
    return [...base, ...adjustedExtras];
  };
  var allMaterials = createUniqueMaterials(baseMaterials, additionalMaterials);

